 world->properties->data=const_cast<char*>("multiplayer");CHECK("lowercase value follows SDK case sensitive fallback to singleplayer",selection.Build(model,request)&&selection.mode==SourcePostProfile::Singleplayer);
 world->properties->data=const_cast<char*>("");CHECK("empty valid WorldType string uses SDK singleplayer fallback",selection.Build(model,request)&&selection.mode==SourcePostProfile::Singleplayer);
 world->properties->data=const_cast<char*>("OtherExtensionMode");CHECK("unrecognized string value uses SDK singleplayer fallback",selection.Build(model,request)&&selection.mode==SourcePostProfile::Singleplayer);
 world->properties->data=const_cast<char*>("MultiPlayer");lstrcpyA(world->properties->type,"real");CHECK("wrong WorldType property type rejects rather than choosing a mode",Rejected(selection,model,request,world->index));lstrcpyA(world->properties->type,"string");world->properties->data=0;CHECK("null typed WorldType data rejects",Rejected(selection,model,request,world->index));world->properties->data=const_cast<char*>("MultiPlayer");
 PrefabScene::Property* original=world->properties;world->properties=0;CHECK("missing WorldType selects singleplayer with source identity",selection.Build(model,request)&&selection.mode==SourcePostProfile::Singleplayer&&selection.sourceNode==world->index);world->properties=original;
 PrefabScene::Property duplicate=*original;duplicate.next=0;original->next=&duplicate;CHECK("duplicate WorldType rejects ambiguous source properties",Rejected(selection,model,request,world->index));original->next=0;
 static char longValue[4097];memset(longValue,'a',4096);longValue[4096]=0;original->data=longValue;CHECK("WorldType string is bounded before equality comparison",Rejected(selection,model,request,world->index));original->data=const_cast<char*>("MultiPlayer");
 request.multiplayer=true;CHECK("automatic and explicit flags conflict before generation",Rejected(selection,model,request));request=SourcePostProfile::Request();request.multiplayer=request.singleplayer=true;CHECK("multiple explicit post passes reject instead of appending both",Rejected(selection,model,request));request=SourcePostProfile::Request();request.multiplayer=true;
 CHECK("matching explicit multiplayer override remains supported",selection.Build(model,request)&&selection.mode==SourcePostProfile::Multiplayer&&!selection.automatic);
 request=SourcePostProfile::Request();request.singleplayer=true;CHECK("explicit source branch mismatch rejects whole selection",Rejected(selection,model,request,world->index));request=SourcePostProfile::Request();request.tutorial=true;
 CHECK("tutorial remains separately named explicit legacy override",selection.Build(model,request)&&selection.mode==SourcePostProfile::Tutorial&&!selection.automatic&&selection.sourceNode==0xffffffffu);
 request=SourcePostProfile::Request();request.automatic=true;unsigned int oldCount=model.count;model.count=100001;CHECK("source node count beyond finite profile rejects before walk",Rejected(selection,model,request));model.count=oldCount;world->index=4;CHECK("invalid model identity order rejects",Rejected(selection,model,request));world->index=0;
 PrefabScene::Node* later=Node(model,"WorldProperties","SinglePlayer");if(!later)ExitProcess(2);CHECK("first authored WorldProperties determines mode not OR of all objects",selection.Build(model,request)&&selection.mode==SourcePostProfile::Multiplayer&&selection.sourceNode==0);world->importedFromPrefab=true;CHECK("authored WorldProperties precedes earlier expanded imported instance",selection.Build(model,request)&&selection.mode==SourcePostProfile::Singleplayer&&selection.sourceNode==later->index);later->importedFromPrefab=true;CHECK("all imported WorldProperties preserve their stable order",selection.Build(model,request)&&selection.mode==SourcePostProfile::Multiplayer&&selection.sourceNode==world->index);
 lstrcpyA(world->className,"WorldPropertiesExtension");CHECK("unrelated class prefix does not select a WorldProperties instance",selection.Build(model,request)&&selection.mode==SourcePostProfile::Singleplayer&&selection.sourceNode==later->index);lstrcpyA(world->className,"WorldProperties");
 CHECK("selection does not mutate source fields or data pointers",world->properties==original&&original->data==(char*)"MultiPlayer"&&later->importedFromPrefab&&world->importedFromPrefab);
 CHECK("valid selection recovers after all rejected attempts",selection.Build(model,request)&&selection.mode==SourcePostProfile::Multiplayer&&!selection.error&&selection.errorNode==0xffffffffu);
 model.Clear();CHECK("selected enum source identity and name survive source destruction",selection.mode==SourcePostProfile::Multiplayer&&selection.sourceNode==0&&SourcePostProfile::Exact(SourcePostProfile::Name(selection.mode),"multiplayer"));selection.Clear();CHECK("Clear resets selection and diagnostics",selection.mode==SourcePostProfile::Disabled&&selection.sourceNode==0xffffffffu&&selection.errorNode==0xffffffffu&&!selection.automatic&&!selection.error);
 char output[MAX_PATH];if(!GetEnvironmentVariableA("FEAR_POST_PROFILE_GUARDS_OUTPUT",output,MAX_PATH))ExitProcess(1);HANDLE file=CreateFileA(output,0x40000000,FILE_SHARE_READ,0,2,FILE_ATTRIBUTE_NORMAL,0);unsigned int header[2]={0x31504753,count};if(file==INVALID_HANDLE_VALUE||!Put(file,header,8)||!Put(file,checks,count*4))ExitProcess(3);CloseHandle(file);for(unsigned int i=0;i<count;i++)if(!checks[i])ExitProcess(4);ExitProcess(0);
